<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Mock payment checkout</title><link rel="stylesheet" href="<?= base_url('css/checkout.css') ?>"><link rel="stylesheet" href="<?= base_url('css/gateway.css') ?>"></head><body><main>
<h1><?= $payment['payment_method'] === 'gcash' ? 'GCash' : ($payment['payment_method'] === 'card' ? 'Credit / Debit Card' : 'Bank Transfer') ?></h1>
<p class="notice">Demo payment — no actual charge. No real financial account, card, wallet, SMS, or bank service is used.</p>
<dl><dt>Reservation reference</dt><dd><?= esc($payment['reservation_reference']) ?></dd><dt>Amount</dt><dd><?= esc($payment['currency']) ?> <?= esc($payment['amount']) ?></dd><dt>Transaction reference</dt><dd><?= esc($payment['transaction_reference']) ?></dd><dt>Status</dt><dd><?= esc(ucfirst($payment['payment_status'])) ?></dd></dl>
<?php $base = 'checkout/' . rawurlencode($payment['transaction_reference']) . '/' . rawurlencode($token); ?>
<?php if ($payment['payment_status'] === 'pending' && $payment['payment_method'] === 'card'): ?>
    <?php if (($demoStage ?? '') === 'verify'): ?><form method="post" action="<?= site_url($base . '/card/verify') ?>"><?= csrf_field() ?><p><strong>Demo verification code: <?= esc($demoOtp ?? 'Restart this demo payment') ?></strong></p><p><label>Verification code <input name="verification_code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" required></label></p><p><small>This code expires in five minutes and is displayed only on this authorized demo checkout page.</small></p><button type="submit">Verify code</button></form>
    <?php elseif (($demoStage ?? '') === 'confirm'): ?><p>Verified test card: <?= esc($payment['payment_identifier_masked'] ?? '') ?></p><p><strong>Review payment: <?= esc($payment['currency']) ?> <?= esc($payment['amount']) ?></strong></p><form method="post" action="<?= site_url($base . '/card/confirm') ?>"><?= csrf_field() ?><button type="submit">Confirm Payment</button></form>
    <?php else: ?><form method="post" action="<?= site_url($base . '/card') ?>"><?= csrf_field() ?><p><label>Fictional cardholder name <input name="cardholder_name" maxlength="100" autocomplete="off" required></label></p><p><label>Test card number <input name="card_number" inputmode="numeric" autocomplete="off" placeholder="4242 4242 4242 4242" required></label></p><p><label>Expiration month <input name="card_expiry_month" inputmode="numeric" autocomplete="off" placeholder="12" maxlength="2" required></label></p><p><label>Expiration year <input name="card_expiry_year" inputmode="numeric" autocomplete="off" placeholder="99" maxlength="2" required></label></p><p><label>Demo CVV <input name="card_cvv" inputmode="numeric" autocomplete="off" placeholder="123" required></label></p><p><small>Supported test cards: 4242 4242 4242 4242 or 5555 5555 5555 4444. Use any fictional name, future expiry, and a 3–4 digit demo CVV. Details are validated but never stored.</small></p><button type="submit">Continue</button></form><?php endif ?>
<?php elseif ($payment['payment_status'] === 'pending' && $payment['payment_method'] === 'gcash' && !isset($gcashStage)): ?><form method="post" action="<?= site_url($base . '/gcash') ?>"><?= csrf_field() ?><p><label>Philippine mobile number <input name="mobile_number" inputmode="tel" autocomplete="tel" placeholder="09XXXXXXXXX" required></label></p><p><small>We validate the number format only; it is not checked against a real GCash account.</small></p><button type="submit">Send demo code</button></form>
<?php elseif ($payment['payment_status'] === 'pending' && $payment['payment_method'] === 'gcash' && ($gcashStage ?? '') === 'verify'): ?><form method="post" action="<?= site_url($base . '/gcash/verify') ?>"><?= csrf_field() ?><p><strong>Demo verification code: <?= esc($demoOtp ?? 'Request a new code') ?></strong></p><p><label>Verification code <input name="verification_code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" required></label></p><p><small>This demo code expires in five minutes. It is not sent by SMS.</small></p><button type="submit">Verify code</button></form><form method="post" action="<?= site_url($base . '/gcash/resend') ?>"><?= csrf_field() ?><p><button class="secondary" type="submit">Generate a new demo code</button></p></form>
<?php elseif ($payment['payment_status'] === 'pending' && $payment['payment_method'] === 'gcash' && ($gcashStage ?? '') === 'confirm'): ?><p>Verified mobile number: <?= esc($payment['gcash_mobile_masked'] ?? '') ?></p><p><strong>Review payment: <?= esc($payment['currency']) ?> <?= esc($payment['amount']) ?></strong></p><form method="post" action="<?= site_url($base . '/gcash/confirm') ?>"><?= csrf_field() ?><button type="submit">Confirm Payment</button></form>
<?php elseif ($payment['payment_status'] === 'pending' && $payment['payment_method'] === 'bank_transfer'): ?>
    <?php if (($demoStage ?? '') === 'verify'): ?><form method="post" action="<?= site_url($base . '/bank-transfer/verify') ?>"><?= csrf_field() ?><p><strong>Demo verification code: <?= esc($demoOtp ?? 'Restart this demo payment') ?></strong></p><p><label>Verification code <input name="verification_code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" required></label></p><p><small>This code expires in five minutes. It is never sent to a real device.</small></p><button type="submit">Verify code</button></form>
    <?php elseif (($demoStage ?? '') === 'confirm'): ?><p>Verified <?= esc($bank ?? 'demo bank') ?> account: <?= esc($payment['payment_identifier_masked'] ?? '') ?></p><p><strong>Review payment: <?= esc($payment['currency']) ?> <?= esc($payment['amount']) ?></strong></p><form method="post" action="<?= site_url($base . '/bank-transfer/confirm') ?>"><?= csrf_field() ?><button type="submit">Confirm Payment</button></form>
    <?php else: ?><form method="post" action="<?= site_url($base . '/bank-transfer') ?>"><?= csrf_field() ?><p><label>Demo bank <select name="bank" required><option value="">Choose a demo bank</option><option>Demo National Bank</option><option>Campus Test Bank</option></select></label></p><p><label>Fictional account number <input name="account_number" inputmode="numeric" autocomplete="off" required></label></p><p><label>Account holder name <input name="account_holder_name" maxlength="100" autocomplete="off" required></label></p><p><small>Demo National Bank uses 10000001 or 10000002; Campus Test Bank uses 20000001 or 20000002. Format validation does not verify a real account.</small></p><button type="submit">Continue</button></form><?php endif ?>
<?php else: ?><p class="result">This transaction is <?= esc($payment['payment_status']) ?>. Terminal results cannot be changed.</p><p><a href="<?= site_url($base . '/receipt') ?>">View printable receipt</a> · <a href="<?= site_url($base . '/receipt/download') ?>">Download HTML receipt</a></p><?php endif ?>
<?php if ($payment['payment_status'] === 'pending'): ?><form method="post" action="<?= site_url($base . '/cancel') ?>"><?= csrf_field() ?><p><button class="secondary" type="submit">Cancel simulated payment</button></p></form><?php endif ?>
<?php $returnSeparator = strpos($returnUrl, '?') === false ? '?' : '&'; ?><p><a href="<?= esc($returnUrl . $returnSeparator . 'payment_reference=' . rawurlencode($payment['transaction_reference']), 'attr') ?>">Return to TechReserve and verify payment</a></p>
</main></body></html>
